import { CHALLENGE_TTL_MS } from "@sigilo/core/session";
import { v } from "convex/values";

import { internalMutation } from "./_generated/server";

const challengeFields = {
  address: v.string(),
  nonce: v.string(),
  issuedAt: v.number(),
  expiresAt: v.number(),
};

/** Store a fresh challenge. The nonce is generated by the calling HTTP action (CSPRNG). */
export const createChallenge = internalMutation({
  args: { address: v.string(), nonce: v.string() },
  returns: v.object(challengeFields),
  handler: async (ctx, { address, nonce }) => {
    const issuedAt = Date.now();
    const challenge = {
      address: address.toLowerCase(),
      nonce,
      issuedAt,
      expiresAt: issuedAt + CHALLENGE_TTL_MS,
    };
    await ctx.db.insert("sessionChallenges", { ...challenge, used: false });
    return challenge;
  },
});

/** Mark a challenge used and return it, or null if it is unknown, used, expired or not theirs. */
export const consumeChallenge = internalMutation({
  args: { address: v.string(), nonce: v.string() },
  returns: v.union(v.null(), v.object(challengeFields)),
  handler: async (ctx, { address, nonce }) => {
    const row = await ctx.db
      .query("sessionChallenges")
      .withIndex("by_nonce", (q) => q.eq("nonce", nonce))
      .unique();
    if (!row || row.used || row.expiresAt < Date.now() || row.address !== address.toLowerCase()) {
      return null;
    }
    await ctx.db.patch("sessionChallenges", row._id, { used: true });
    return {
      address: row.address,
      nonce: row.nonce,
      issuedAt: row.issuedAt,
      expiresAt: row.expiresAt,
    };
  },
});
